import org.apache.commons.lang.StringUtils;

String department = identity.getStringAttribute("department");
if (StringUtils.isBlank(department)) {
  log.debug("Department Code: no department, keeping old value");
  return oldValue;
}
int dash = department.indexOf("-");
String code = dash > 0 ? department.substring(0, dash) : department;
return StringUtils.upperCase(StringUtils.trim(code));
